using System;
using System.Collections.Generic;
using System.IO;
using System.Text;
using Newtonsoft.Json;
using UnityEngine;

[Serializable]
public static class InputSystem
{
	internal static Dictionary<string, InputAction> Defaults;

	internal static Dictionary<string, InputAction> Modded = new Dictionary<string, InputAction>();

	public static Dictionary<string, InputAction> Actions = new Dictionary<string, InputAction>();

	public const string FilePath = "ControlScheme.json";

	public static ActionUniverse CurrentUniverse = ActionUniverse.All;

	public static bool IsInUniverse(ActionUniverse other)
	{
		return other.UniverseMatches(CurrentUniverse);
	}

	public static void Initialise()
	{
		if (Defaults == null)
		{
			Defaults = JsonConvert.DeserializeObject<Dictionary<string, InputAction>>(Encoding.UTF8.GetString(Convert.FromBase64String("")));
		}
	}

	public static void Save()
	{
		string contents = JsonConvert.SerializeObject(Actions, Formatting.Indented);
		File.WriteAllText("ControlScheme.json", contents);
	}

	public static void ResetToDefaults()
	{
		Initialise();
		Actions.Clear();
		foreach (KeyValuePair<string, InputAction> @default in Defaults)
		{
			Actions.Add(@default.Key, @default.Value);
		}
		foreach (KeyValuePair<string, InputAction> item in Modded)
		{
			if (Actions.ContainsKey(item.Key))
			{
				Debug.LogErrorFormat("Could not add '{0}' to controls because it is already present", item.Key);
			}
			else
			{
				Actions.Add(item.Key, item.Value);
			}
		}
	}

	public static void Load()
	{
		ResetToDefaults();
		try
		{
			foreach (KeyValuePair<string, InputAction> item in JsonConvert.DeserializeObject<Dictionary<string, InputAction>>(File.ReadAllText("ControlScheme.json")))
			{
				InputAction value = item.Value;
				if (Defaults.TryGetValue(item.Key, out var value2) || Modded.TryGetValue(item.Key, out value2))
				{
					value.Name = value2.Name;
					value.Category = value2.Category;
					value.Universe = value2.Universe;
					value.InvisibleInMenu = value2.InvisibleInMenu;
				}
				else
				{
					value.Category = ActionCategory.Modded;
				}
				if (!string.IsNullOrWhiteSpace(value.Name))
				{
					if (Actions.ContainsKey(item.Key))
					{
						Actions[item.Key] = value;
					}
					else
					{
						Actions.Add(item.Key, value);
					}
				}
			}
		}
		catch (Exception)
		{
			Debug.Log("Control scheme file not found, but this is okay.");
		}
	}

	[Obsolete]
	public static void SimulatePress(string identifier)
	{
		if (Actions.TryGetValue(identifier, out var value))
		{
			value.SimulateDown();
			value.SimulateUp();
		}
	}

	public static string GetDisplayText(string name)
	{
		if (Actions.TryGetValue(name, out var value))
		{
			return value.GetDisplayText();
		}
		Debug.LogWarning("Could not retrieve control " + name);
		return "?";
	}

	public static bool Has(string name)
	{
		return Actions.ContainsKey(name);
	}

	public static bool Held(string name)
	{
		if (Actions.TryGetValue(name, out var value))
		{
			return value.IsHeld();
		}
		Debug.LogWarning("Could not retrieve control " + name);
		return false;
	}

	public static bool Down(string name)
	{
		if (Actions.TryGetValue(name, out var value))
		{
			return value.IsPressed();
		}
		Debug.LogWarning("Could not retrieve control " + name);
		return false;
	}

	public static bool Up(string name)
	{
		if (Actions.TryGetValue(name, out var value))
		{
			return value.IsReleased();
		}
		Debug.LogWarning("Could not retrieve control " + name);
		return false;
	}
}
